package dev.nexflow.dashboard;
import dev.nexflow.order.*; import dev.nexflow.product.ProductRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class DashboardService {private final OrderRepository orders;private final ProductRepository products;private final OrderService orderService;public DashboardService(OrderRepository o,ProductRepository p,OrderService s){orders=o;products=p;orderService=s;}
 @Transactional(readOnly=true) public DashboardDtos.View get(){List<OrderEntity> all=orders.findAllByOrderByCreatedAtDesc();List<OrderEntity> valid=all.stream().filter(o->o.getStatus()!=OrderStatus.CANCELLED).toList();BigDecimal revenue=valid.stream().map(OrderEntity::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal avg=valid.isEmpty()?BigDecimal.ZERO:revenue.divide(BigDecimal.valueOf(valid.size()),2,RoundingMode.HALF_UP);long critical=products.findAll().stream().filter(p->p.isActive()&&p.availableQuantity()<=p.getMinStock()).count();Map<String,Long> counts=new LinkedHashMap<>();for(OrderStatus s:OrderStatus.values())counts.put(s.name(),all.stream().filter(o->o.getStatus()==s).count());Map<UUID,int[]> qty=new HashMap<>();Map<UUID,BigDecimal> rev=new HashMap<>();Map<UUID,String> names=new HashMap<>();for(OrderEntity o:valid)for(OrderItem i:o.getItems()){qty.computeIfAbsent(i.getProductId(),k->new int[]{0})[0]+=i.getQuantity();rev.merge(i.getProductId(),i.getTotal(),BigDecimal::add);names.put(i.getProductId(),i.getProductName());}List<DashboardDtos.TopProduct> top=qty.entrySet().stream().sorted((a,b)->Integer.compare(b.getValue()[0],a.getValue()[0])).limit(5).map(e->new DashboardDtos.TopProduct(names.get(e.getKey()),e.getValue()[0],rev.get(e.getKey()))).toList();return new DashboardDtos.View(revenue,all.size(),avg,critical,counts,all.stream().limit(6).map(orderService::view).toList(),top);}
}
